      SUBROUTINE ENRICH(NM)CC     CALCULATES NEW TRANSFER MATRIX ABOUT DISPLACED TRAJECTORYCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'COACOM.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'      INCLUDE 'RA.CIN'      INCLUDE 'RC3.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TA.CIN'      INCLUDE 'TC3.CIN'      INCLUDE 'U.CIN'      INCLUDE 'UA.CIN'      INCLUDE 'UC3.CIN'CC---------------------------------------------------------------------C     TRANSFER OF MATRICES TO WORK AREASC      IF (NM .EQ. 0) THEN        DO 5 JK = 1, 36    5   RAL(JK) = RL(JK)        IF (NORD1 .GE. 2) THEN          DO 10 JKL = 1, 105   10     TAL(JKL) = TL(JKL)        ENDIF        IF (NORD1 .GE. 3) THEN          DO 12 JKLM = 1, 280   12     UAL(JKLM) = UL(JKLM)        ENDIF      ELSE IF (NM .EQ. 1) THEN        DO 15 JK = 1, 36   15   RAL(JK) = RVL(JK)        IF (NORD1 .GE. 2) THEN          DO 20 JKL = 1, 105   20     TAL(JKL) = TVL(JKL)        ENDIF        IF (NORD1 .GE. 3) THEN          DO 22 JKLM = 1, 280   22     UAL(JKLM) = UVL(JKLM)        ENDIF      ELSE IF (NM .EQ. 3) THEN        DO 25 JK = 1, 36   25   RAL(JK) = RC3L(JK)        IF (NORD1 .GE. 2) THEN          DO 30 JKL = 1, 105   30     TAL(JKL) = TC3L(JKL)        ENDIF        IF (NORD1 .GE. 3) THEN          DO 35 JKLM = 1, 280   35     UAL(JKLM) = UC3L(JKLM)        ENDIF      ENDIFC   50 DO 60 J = 1, 6   60 COA(J) = CO(J)CC     CONTRIBUTION OF HIGHER-ORDER MATRICES TO OFF-AXIS LOWER ORDERC  100 IF (NORD1 .GE. 2) CALL ENRIC2      IF (NORD1 .GE. 3) CALL ENRIC3CC     TRANSFER OF MATRICES FROM WORK AREASC      IF (NM .EQ. 0) THEN        DO 105 JK = 1, 36  105   RL(JK) = RAL(JK)        IF (NORD2 .GE. 2) THEN          DO 110 JKL = 1, 105  110     TL(JKL) = TAL(JKL)        ENDIF        IF (NORD2 .GE. 3) THEN          DO 112 JKLM = 1, 280  112     UL(JKLM) = UAL(JKLM)        ENDIF      ELSE IF (NM .EQ. 1) THEN        DO 115 JK = 1, 36  115   RVL(JK) = RAL(JK)        IF (NORD2 .GE. 2) THEN          DO 120 JKL = 1, 105  120     TVL(JKL) = TAL(JKL)        ENDIF        IF (NORD2 .GE. 3) THEN          DO 122 JKLM = 1, 280  122     UVL(JKLM) = UAL(JKLM)        ENDIF      ELSE IF (NM .EQ. 3) THEN        DO 125 JK = 1, 36  125   RC3L(JK) = RAL(JK)        IF (NORD2 .GE. 2) THEN          DO 130 JKL = 1, 105  130     TC3L(JKL) = TAL(JKL)        ENDIF        IF (NORD2 .GE. 3) THEN          DO 132 JKLM = 1, 280  132     UC3L(JKLM) = UAL(JKLM)        ENDIF      ENDIFC  200 RETURN      END